#!/usr/bin/env python3
"""Verify the self-signed TLS certificate at /app/ssl/server.crt."""
import subprocess
import sys
import datetime
import re

CERT_PATH = "/app/ssl/server.crt"


def load_cert_text():
    result = subprocess.run(
        ["openssl", "x509", "-in", CERT_PATH, "-noout", "-subject", "-enddate"],
        capture_output=True, text=True,
    )
    if result.returncode != 0:
        raise RuntimeError(result.stderr.strip())
    return result.stdout


def parse_common_name(text):
    m = re.search(r"CN\s*=\s*([^,/\n]+)", text)
    return m.group(1).strip() if m else None


def parse_expiration(text):
    m = re.search(r"notAfter=(.+)", text)
    if not m:
        return None
    raw = m.group(1).strip()
    dt = datetime.datetime.strptime(raw, "%b %d %H:%M:%S %Y %Z")
    return dt.strftime("%Y-%m-%d")


def main():
    import os
    if not os.path.exists(CERT_PATH):
        print("Certificate file not found: %s" % CERT_PATH)
        sys.exit(1)
    try:
        text = load_cert_text()
    except Exception as exc:
        print("Failed to load certificate: %s" % exc)
        sys.exit(1)

    cn = parse_common_name(text)
    expiration = parse_expiration(text)

    print("Certificate loaded successfully from %s" % CERT_PATH)
    print("Common Name: %s" % cn)
    print("Expiration Date: %s" % expiration)

    if not cn or not expiration:
        print("Certificate verification failed")
        sys.exit(1)

    print("Certificate verification successful")


if __name__ == "__main__":
    main()
